from abc import ABC, abstractmethod
from typing import Protocol

# Using Abstract Base Class
class DatabaseInterface(ABC):
    @abstractmethod
    def connect(self):
        pass

    @abstractmethod
    def execute_query(self, query: str):
        pass

    @abstractmethod
    def close(self):
        pass

    @abstractmethod
    def get_connection_info(self) -> str:
        pass

# Using Protocol (Python 3.8+) - Structural typing
class DatabaseProtocol(Protocol):
    def connect(self) -> bool:
        ...

    def execute_query(self, query: str) -> list:
        ...

    def close(self) -> None:
        ...

    def get_connection_info(self) -> str:
        ...

class MySQLDatabase:
    def __init__(self, host, port, database, username, password):
        self.host = host
        self.port = port
        self.database = database
        self.username = username
        self.password = password
        self.connected = False

    def connect(self):
        # Simulate connection
        self.connected = True
        return True

    def execute_query(self, query: str):
        if not self.connected:
            raise ConnectionError("Not connected to database")
        # Simulate query execution
        return [{"result": f"Executed: {query}"}]

    def close(self):
        self.connected = False

    def get_connection_info(self) -> str:
        return f"MySQL: {self.host}:{self.port}/{self.database}"

class SQLiteDatabase:
    def __init__(self, file_path):
        self.file_path = file_path
        self.connected = False

    def connect(self):
        # Simulate connection
        self.connected = True
        return True

    def execute_query(self, query: str):
        if not self.connected:
            raise ConnectionError("Not connected to database")
        # Simulate query execution
        return [{"result": f"Executed: {query}"}]

    def close(self):
        self.connected = False

    def get_connection_info(self) -> str:
        return f"SQLite: {self.file_path}"

# Database manager that works with any database implementing the interface
class DatabaseManager:
    def __init__(self, database: DatabaseProtocol):
        self.database = database

    def perform_operation(self, query: str):
        try:
            self.database.connect()
            result = self.database.execute_query(query)
            return result
        finally:
            self.database.close()

    def get_database_info(self):
        return self.database.get_connection_info()

# Usage
mysql_db = MySQLDatabase("localhost", 3306, "testdb", "user", "pass")
sqlite_db = SQLiteDatabase("test.db")

databases = [mysql_db, sqlite_db]

for db in databases:
    manager = DatabaseManager(db)
    print(f"Database: {manager.get_database_info()}")
    result = manager.perform_operation("SELECT * FROM users")
    print(f"Result: {result}")
    print()
