from abc import ABC, abstractmethod

class Button(ABC):
    @abstractmethod
    def render(self):
        pass

    @abstractmethod
    def click(self):
        pass

class TextBox(ABC):
    @abstractmethod
    def render(self):
        pass

    @abstractmethod
    def input_text(self, text):
        pass

class CheckBox(ABC):
    @abstractmethod
    def render(self):
        pass

    @abstractmethod
    def check(self):
        pass

# Windows UI Components
class WindowsButton(Button):
    def render(self):
        return "Rendering Windows button"

    def click(self):
        return "Windows button clicked"

class WindowsTextBox(TextBox):
    def render(self):
        return "Rendering Windows text box"

    def input_text(self, text):
        return f"Windows text box: {text}"

class WindowsCheckBox(CheckBox):
    def render(self):
        return "Rendering Windows checkbox"

    def check(self):
        return "Windows checkbox checked"

# Mac UI Components
class MacButton(Button):
    def render(self):
        return "Rendering Mac button"

    def click(self):
        return "Mac button clicked"

class MacTextBox(TextBox):
    def render(self):
        return "Rendering Mac text box"

    def input_text(self, text):
        return f"Mac text box: {text}"

class MacCheckBox(CheckBox):
    def render(self):
        return "Rendering Mac checkbox"

    def check(self):
        return "Mac checkbox checked"

# Abstract Factory
class UIFactory(ABC):
    @abstractmethod
    def create_button(self) -> Button:
        pass

    @abstractmethod
    def create_textbox(self) -> TextBox:
        pass

    @abstractmethod
    def create_checkbox(self) -> CheckBox:
        pass

class WindowsUIFactory(UIFactory):
    def create_button(self) -> Button:
        return WindowsButton()

    def create_textbox(self) -> TextBox:
        return WindowsTextBox()

    def create_checkbox(self) -> CheckBox:
        return WindowsCheckBox()

class MacUIFactory(UIFactory):
    def create_button(self) -> Button:
        return MacButton()

    def create_textbox(self) -> TextBox:
        return MacTextBox()

    def create_checkbox(self) -> CheckBox:
        return MacCheckBox()

# Application that uses the factory
class Application:
    def __init__(self, factory: UIFactory):
        self.factory = factory
        self.button = factory.create_button()
        self.textbox = factory.create_textbox()
        self.checkbox = factory.create_checkbox()

    def render_ui(self):
        print(self.button.render())
        print(self.textbox.render())
        print(self.checkbox.render())

    def interact(self):
        print(self.button.click())
        print(self.textbox.input_text("Hello World"))
        print(self.checkbox.check())

# Usage
print("Windows Application:")
windows_app = Application(WindowsUIFactory())
windows_app.render_ui()
windows_app.interact()

print("\nMac Application:")
mac_app = Application(MacUIFactory())
mac_app.render_ui()
mac_app.interact()
```

