from abc import ABC, abstractmethod

class PaymentStrategy(ABC):
    @abstractmethod
    def pay(self, amount):
        pass

    @abstractmethod
    def get_payment_info(self):
        pass

class CreditCardPayment(PaymentStrategy):
    def __init__(self, card_number, expiry_date, cvv):
        self.card_number = card_number
        self.expiry_date = expiry_date
        self.cvv = cvv

    def pay(self, amount):
        return f"Paid ${amount} using Credit Card ending in {self.card_number[-4:]}"

    def get_payment_info(self):
        return f"Credit Card: ****{self.card_number[-4:]}"

class PayPalPayment(PaymentStrategy):
    def __init__(self, email):
        self.email = email

    def pay(self, amount):
        return f"Paid ${amount} using PayPal account {self.email}"

    def get_payment_info(self):
        return f"PayPal: {self.email}"

class BankTransferPayment(PaymentStrategy):
    def __init__(self, account_number, routing_number):
        self.account_number = account_number
        self.routing_number = routing_number

    def pay(self, amount):
        return f"Paid ${amount} using Bank Transfer from account ending in {self.account_number[-4:]}"

    def get_payment_info(self):
        return f"Bank Transfer: ****{self.account_number[-4:]}"

class ShoppingCart:
    def __init__(self):
        self.items = []
        self.payment_strategy = None

    def add_item(self, item, price):
        self.items.append((item, price))

    def set_payment_strategy(self, strategy: PaymentStrategy):
        self.payment_strategy = strategy

    def checkout(self):
        if not self.payment_strategy:
            raise ValueError("No payment strategy set")

        total = sum(price for _, price in self.items)
        print(f"Total amount: ${total}")
        print(f"Payment method: {self.payment_strategy.get_payment_info()}")
        print(self.payment_strategy.pay(total))

        # Clear cart after successful payment
        self.items.clear()

# Usage
cart = ShoppingCart()
cart.add_item("Laptop", 999.99)
cart.add_item("Mouse", 25.50)

# Use different payment strategies
strategies = [
    CreditCardPayment("1234567890123456", "12/25", "123"),
    PayPalPayment("user@example.com"),
    BankTransferPayment("12345678", "123456789")
]

for strategy in strategies:
    cart.set_payment_strategy(strategy)
    cart.checkout()
    print()
```
